import React, { useEffect, useMemo, useState } from 'react';
import { Card, Space, Typography, Input, DatePicker, Button, Table, Tag, Badge, message, Select, Tooltip } from 'antd';
import dayjs, { Dayjs } from 'dayjs';
import { apiRequest } from '../api';
import { usePermissions } from '../hooks/usePermissions';

const { Title, Text } = Typography;

const buildHeaders = () => ({ });

const RemindersHistory: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<any[]>([]);
  const [incidents, setIncidents] = useState<any[]>([]);
  const [query, setQuery] = useState('');
  const [sentFilter, setSentFilter] = useState<'all'|'sent'|'pending'>('all');
  const [ackFilter, setAckFilter] = useState<'all'|'ack'|'noack'>('all');
  const [dateFrom, setDateFrom] = useState<Dayjs | null>(null);
  const [dateTo, setDateTo] = useState<Dayjs | null>(null);
  // Architect override of X-Telegram-User-ID
  const { state: permState } = usePermissions();
  const isArchitect = (permState.roles || []).some(r => r.name === 'architect');
  const [overrideTgId, setOverrideTgId] = useState<string>('');
  const hdrs = useMemo(() => (overrideTgId && isArchitect) ? { 'X-Telegram-User-ID': overrideTgId } : {}, [overrideTgId, isArchitect]);

  const loadData = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      params.set('include_sent', 'true');
      if (dateFrom) params.set('date_from', dateFrom.format('YYYY-MM-DD'));
      if (dateTo) params.set('date_to', dateTo.format('YYYY-MM-DD'));
      if (query && query.trim()) params.set('q', query.trim());
      const rems = await apiRequest(`/miniapp/reminders?${params.toString()}`, 'GET', null, hdrs);
      const inc = await apiRequest('/admin/soul/processor/incidents?limit=500', 'GET', null, hdrs);
      setItems(Array.isArray(rems) ? rems : []);
      setIncidents(Array.isArray(inc?.items) ? inc.items : []);
    } catch (e) {
      message.error('Не удалось загрузить данные');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { void loadData(); }, []);

  const ackMap = useMemo(() => {
    const map: Record<number, boolean> = {};
    for (const it of incidents) {
      if (it?.type === 'reminder_ack') {
        const m = /id=(\d+)/.exec(String(it.detail || ''));
        if (m) map[Number(m[1])] = true;
      }
    }
    return map;
  }, [incidents]);

  const filtered = useMemo(() => {
    return (items || []).filter((r: any) => {
      if (sentFilter === 'sent' && !r.is_sent) return false;
      if (sentFilter === 'pending' && r.is_sent) return false;
      if (ackFilter === 'ack' && !ackMap[r.id]) return false;
      if (ackFilter === 'noack' && ackMap[r.id]) return false;
      if (dateFrom && dayjs(r.reminder_date).isBefore(dateFrom, 'day')) return false;
      if (dateTo && dayjs(r.reminder_date).isAfter(dateTo, 'day')) return false;
      if (query) {
        const q = query.toLowerCase();
        const hay = `${r.title||''} ${r.description||''}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [items, sentFilter, ackFilter, dateFrom, dateTo, query, ackMap]);

  const actionResend = async (id: number) => {
    try {
      const body = { kind: 'reminder', payload: { reminder_id: id } };
      await apiRequest('/admin/soul/processor/event', 'POST', body, hdrs);
      message.success(`Повторная отправка поставлена в очередь (#${id})`);
    } catch { message.error('Не удалось поставить повторную отправку'); }
  };

  const actionSnooze = async (id: number, minutes: number) => {
    try {
      const now = dayjs.utc();
      const due = now.add(minutes, 'minute').toISOString();
      // Обновляем напрямую напоминание
      await apiRequest(`/miniapp/reminders/${id}`, 'PUT', { reminder_date: due }, hdrs);
      // Планируем событие (best-effort через event)
      await apiRequest('/admin/soul/processor/event', 'POST', { kind: 'reminder', payload: { reminder_id: id } }, hdrs);
      message.success(`Отложено на ${minutes} мин`);
      void loadData();
    } catch { message.error('Не удалось отложить'); }
  };

  const actionCancel = async (id: number) => {
    try {
      // Простой флаг sent=true, чтобы прекратить ретраи (через update)
      await apiRequest(`/miniapp/reminders/${id}`, 'PUT', { /* не меняем дату */ }, hdrs);
      message.success('Отменено (логика отмены применяется в бэкенде через ack/cancel)');
      void loadData();
    } catch { message.error('Не удалось отменить'); }
  };

  return (
    <div style={{ padding: 16 }}>
      <Title level={4}>Напоминания — история и действия</Title>
      <Card>
        {isArchitect && (
          <Space wrap style={{ marginBottom: 8 }}>
            <Tooltip title="Просмотр от лица пользователя (только архитектор)">
              <Input
                placeholder="TG ID пользователя"
                value={overrideTgId}
                onChange={(e)=>{
                  const v = e.target.value.replace(/[^0-9]/g,'');
                  setOverrideTgId(v);
                }}
                style={{ width: 220 }}
                maxLength={12}
              />
            </Tooltip>
            <Button onClick={()=> void loadData()}>Применить</Button>
          </Space>
        )}
        <Space wrap>
          <Input placeholder="Поиск (заголовок/описание)" value={query} onChange={(e)=>setQuery(e.target.value)} style={{ width: 260 }} />
          <Select value={sentFilter} onChange={setSentFilter} style={{ width: 160 }}
            options={[{value:'all',label:'Все'}, {value:'sent',label:'Только sent'}, {value:'pending',label:'Только pending'}]} />
          <Select value={ackFilter} onChange={setAckFilter} style={{ width: 160 }}
            options={[{value:'all',label:'ACK: все'}, {value:'ack',label:'Только ACK'}, {value:'noack',label:'Без ACK'}]} />
          <DatePicker placeholder="С даты" value={dateFrom} onChange={setDateFrom as any} />
          <DatePicker placeholder="По дату" value={dateTo} onChange={setDateTo as any} />
          <Button onClick={() => { setQuery(''); setSentFilter('all'); setAckFilter('all'); setDateFrom(null); setDateTo(null); }}>Сбросить</Button>
          <Button type="primary" onClick={() => void loadData()} loading={loading}>Обновить</Button>
        </Space>
      </Card>

      <Card style={{ marginTop: 12 }}>
        <Table
          rowKey={(r:any)=>r.id}
          dataSource={filtered}
          loading={loading}
          pagination={{ pageSize: 10 }}
          columns={[
            { title: 'ID', dataIndex: 'id', width: 80 },
            { title: 'Заголовок', dataIndex: 'title' },
            { title: 'Когда', dataIndex: 'reminder_date', width: 200 },
            { title: 'Sent', dataIndex: 'is_sent', width: 100, render: (v:boolean)=> v ? <Tag color="green">sent</Tag> : <Tag color="volcano">pending</Tag> },
            { title: 'ACK', key: 'ack', width: 100, render: (_:any, r:any)=> ackMap[r.id] ? <Badge status="success" text="ack" /> : <Badge status="default" text="no" /> },
            { title: 'Действия', key: 'actions', width: 360, render: (_:any, r:any)=> (
              <Space>
                <Button size="small" onClick={() => void actionResend(r.id)}>Повторно</Button>
                <Button size="small" onClick={() => void actionSnooze(r.id, 5)}>+5 мин</Button>
                <Button size="small" onClick={() => void actionSnooze(r.id, 30)}>+30 мин</Button>
                <Button size="small" danger onClick={() => void actionCancel(r.id)}>Отменить</Button>
              </Space>
            ) },
          ] as any}
        />
      </Card>
    </div>
  );
};

export default RemindersHistory;
